BEGIN;
create temp table assertion_count(n integer);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create temp table st(k text primary key,v jsonb);
insert into public.properties(id,org_id,name)values('ee580000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','Checklist SQL fixture'),('ee580000-0000-4000-8000-000000000002','22222222-2222-2222-2222-222222222222','Other checklist SQL fixture');
create function pg_temp.read_tasks(b jsonb default'{}',p uuid default'ee580000-0000-4000-8000-000000000001')returns jsonb language sql as $$select public.read_onboarding_tasks(p,'11111111-1111-1111-1111-111111111111',b)$$;
create function pg_temp.decide(i uuid,b jsonb,p uuid default'ee580000-0000-4000-8000-000000000001')returns jsonb language sql as $$select public.decide_onboarding_task(i,p,'11111111-1111-1111-1111-111111111111',b)$$;
create function pg_temp.fields()returns jsonb language sql as $$select'{"name":"Review client checklist","description":"Exact private task description","category":"general","priority":50,"status":"pending","notes":"Private task notes","blockedReason":""}'::jsonb$$;
create function pg_temp.edit(i uuid,op text default'save',s text default'pending')returns jsonb language plpgsql as $$declare b jsonb;begin b:=jsonb_build_object('operation',op,'taskId',i,'expectedHash',public.knowledge_hash(public.onboarding_task_snapshot(i)),'reason','Reviewed exact checklist change');if op='save'then b:=b||jsonb_build_object('fields',pg_temp.fields()||jsonb_build_object('status',s),'confirmed',true);end if;return b;end$$;
select pg_temp.check_it(pg_temp.read_tasks()->'stats'->>'total'='0','empty counts are truthful');
select public.create_default_onboarding_tasks('ee580000-0000-4000-8000-000000000001');
select public.create_default_onboarding_tasks('ee580000-0000-4000-8000-000000000001');
select pg_temp.check_it(pg_temp.read_tasks()->'stats'->>'total'='9','defaults idempotent');
select pg_temp.check_it((select count(*)from public.onboarding_task_decisions where property_id='ee580000-0000-4000-8000-000000000001'and origin='default_setup'and actor_id is null)=9,'defaults retain actual system identity');
select pg_temp.check_it((select count(*)from public.shared_action_events where property_id='ee580000-0000-4000-8000-000000000001'and service_principal='property.setup'and actor_id is null and action='checklist.initialized')=9,'initialization activity recorded without invented person');
insert into st values('create',jsonb_build_object('operation','create','fields',pg_temp.fields(),'confirmed',false,'reason','Review custom checklist task'));
insert into st values('created',pg_temp.decide('ee580000-0000-4000-8000-000000000010',(select v from st where k='create')));
select pg_temp.check_it(v->>'state'='saved'and v->>'revision'='1'and v->'verifiedReadiness'='false','custom task created with review receipt')from st where k='created';
select pg_temp.check_it(pg_temp.decide('ee580000-0000-4000-8000-000000000010',(select v from st where k='create'))->>'state'='replayed','lost create replay does not duplicate');
select pg_temp.check_it(pg_temp.decide('ee580000-0000-4000-8000-000000000010',(select v||'{"reason":"Different reviewed task"}'from st where k='create'))->>'state'='request_conflict','replay content immutable');
select pg_temp.check_it(pg_temp.decide('ee580000-0000-4000-8000-000000000010',(select v from st where k='create'),'ee580000-0000-4000-8000-000000000002')->>'state'='request_conflict','request is property scoped');
insert into st values('old',pg_temp.edit('ee580000-0000-4000-8000-000000000010'));
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.edit('ee580000-0000-4000-8000-000000000010','save','skipped'))->>'state'='saved','skip decision saved');
select pg_temp.check_it(pg_temp.read_tasks()->'stats'->>'skipped'='1','skipped tasks visible in complete counts');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),(select v from st where k='old'))->>'state'='task_changed','stale form cannot replace newer status');
do $$begin begin perform pg_temp.decide(gen_random_uuid(),pg_temp.edit('ee580000-0000-4000-8000-000000000010','save','completed')||'{"confirmed":false}');raise exception 'expected rejection'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'reported completion requires confirmation');end;begin perform pg_temp.decide(gen_random_uuid(),pg_temp.edit('ee580000-0000-4000-8000-000000000010','save','blocked'));raise exception 'expected rejection'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'blocked status requires explanation');end;end$$;
select pg_temp.decide('ee580000-0000-4000-8000-000000000011',pg_temp.edit('ee580000-0000-4000-8000-000000000010','save','completed'));
select pg_temp.check_it((select completed_by='11111111-1111-1111-1111-111111111111'and completed_at is not null from public.onboarding_tasks where id='ee580000-0000-4000-8000-000000000010'),'reported completion has actual actor and timestamp');
select pg_temp.check_it(not exists(select 1 from public.integration_credentials where property_id='ee580000-0000-4000-8000-000000000001')and not exists(select 1 from public.documents where property_id='ee580000-0000-4000-8000-000000000001')and(select onboarding_completed_at is null from public.properties where id='ee580000-0000-4000-8000-000000000001'),'manual completed does not activate connections publish knowledge or complete property setup');
select pg_temp.check_it((select before_state->'task'->>'status'='skipped'and after_state->'task'->>'status'='completed'from public.onboarding_task_decisions where id='ee580000-0000-4000-8000-000000000011'),'exact beforeafter retained');
select pg_temp.decide(gen_random_uuid(),pg_temp.edit('ee580000-0000-4000-8000-000000000010','archive'));
select pg_temp.check_it(pg_temp.read_tasks()->'stats'->>'total'='9'and pg_temp.read_tasks()->'stats'->>'archived'='1'and pg_temp.read_tasks()->'stats'->>'completed'='0','archived tasks excluded from active progress but retained');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.edit('ee580000-0000-4000-8000-000000000010'))->>'state'='task_archived','archived task editing held');
select pg_temp.decide(gen_random_uuid(),pg_temp.edit('ee580000-0000-4000-8000-000000000010','restore'));
select pg_temp.check_it((select status='completed'from public.onboarding_tasks where id='ee580000-0000-4000-8000-000000000010'),'restore preserves reported completion');
select pg_temp.decide(gen_random_uuid(),pg_temp.edit('ee580000-0000-4000-8000-000000000010','save','in_progress'));
select pg_temp.check_it((select completed_at is null and completed_by is null from public.onboarding_tasks where id='ee580000-0000-4000-8000-000000000010'),'reopen clears current completion attribution but retains prior history');
-- Legacy task adoption preserves fields the supported editor does not edit.
insert into public.onboarding_tasks(id,property_id,task_type,task_name,status,assigned_to,due_date,metadata)values('ee580000-0000-4000-8000-000000000020','ee580000-0000-4000-8000-000000000001','legacy_custom','Earlier task','pending','11111111-1111-1111-1111-111111111111','2030-01-01','{"legacy":"preserved"}');
select pg_temp.check_it(pg_temp.read_tasks('{"kind":"task","taskId":"ee580000-0000-4000-8000-000000000020"}')->'snapshot'->'workspace'='null','legacy task has honest unrecorded provenance');
select pg_temp.decide('ee580000-0000-4000-8000-000000000021',pg_temp.edit('ee580000-0000-4000-8000-000000000020'));
select pg_temp.check_it((select task_type='legacy_custom'and assigned_to='11111111-1111-1111-1111-111111111111'and due_date='2030-01-01'and metadata='{"legacy":"preserved"}'from public.onboarding_tasks where id='ee580000-0000-4000-8000-000000000020'),'unsupported legacy metadata preserved exactly');
select pg_temp.check_it((select before_state->'workspace'='null'and before_state->'task'->>'task_name'='Earlier task'from public.onboarding_task_decisions where id='ee580000-0000-4000-8000-000000000021'),'legacy beforestate retained on adoption');
select pg_temp.check_it(pg_temp.read_tasks('{"kind":"task","taskId":"ee580000-0000-4000-8000-000000000020"}','ee580000-0000-4000-8000-000000000002')->>'state'='not_found','crossproperty details withheld');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.edit('ee580000-0000-4000-8000-000000000020'),'ee580000-0000-4000-8000-000000000002')->>'state'='not_found','crossproperty edits withheld');
select pg_temp.check_it(pg_temp.decide('ee580000-0000-4000-8000-000000000030',jsonb_build_object('operation','cancel_unused','inputHash',repeat('a',64),'reason','Stop unused task request'))->>'state'='cancelled','unused request cancellation retained');
select pg_temp.check_it(pg_temp.decide('ee580000-0000-4000-8000-000000000030',(select v from st where k='create'))->>'state'='decision_cancelled','late original request blocked by cancellation');
select pg_temp.check_it(pg_temp.decide('ee580000-0000-4000-8000-000000000011',jsonb_build_object('operation','cancel_unused','inputHash',repeat('b',64),'reason','Stop unused task request'))->>'state'='replayed','cancellation cannot undo saved decision');
select pg_temp.check_it(pg_temp.read_tasks('{"kind":"decision","decisionId":"ee580000-0000-4000-8000-000000000011"}')->>'state'='ready','exact saved receipt recoverable');
-- Current manager authority, not a stale browser identity.
update public.profiles set role='viewer'where id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(pg_temp.read_tasks()->'canManage'='false','viewer reads without mutation controls');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),(select v from st where k='create'))->>'state'='forbidden','viewer mutation forbidden');
update public.profiles set role='admin'where id='11111111-1111-1111-1111-111111111111';
insert into public.organizations(id,name)values('ee580000-0000-4000-8000-000000000090','Checklist transfer SQL fixture');
update public.profiles set org_id='ee580000-0000-4000-8000-000000000090'where id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(pg_temp.read_tasks()->>'state'='forbidden','member transfer hides former property history');
SET LOCAL session_replication_role=replica;
UPDATE public.properties SET current_vertical_profile_version_id=NULL WHERE id='ee580000-0000-4000-8000-000000000001';
DELETE FROM public.property_vertical_profile_versions WHERE property_id='ee580000-0000-4000-8000-000000000001';
SET LOCAL session_replication_role=origin;
update public.properties set org_id='ee580000-0000-4000-8000-000000000090'where id='ee580000-0000-4000-8000-000000000001';
select pg_temp.check_it(pg_temp.read_tasks()->>'state'='scope_changed','property transfer does not rebind private task evidence');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.edit('ee580000-0000-4000-8000-000000000020'))->>'state'='scope_changed','property transfer editing held');
update public.properties set org_id='22222222-2222-2222-2222-222222222222'where id='ee580000-0000-4000-8000-000000000001';update public.profiles set org_id='22222222-2222-2222-2222-222222222222'where id='11111111-1111-1111-1111-111111111111';
select set_config('p11.checklist_scope','',true);
do $$begin begin update public.onboarding_tasks set status='pending'where id='ee580000-0000-4000-8000-000000000010';raise exception 'expected guard'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'adopted raw update blocked');end;begin delete from public.onboarding_tasks where id='ee580000-0000-4000-8000-000000000010';raise exception 'expected guard'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'adopted raw delete blocked');end;begin update public.onboarding_task_decisions set input='{}'where id='ee580000-0000-4000-8000-000000000011';raise exception 'expected guard'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'decision evidence immutable');end;end$$;
select pg_temp.check_it(not has_table_privilege('authenticated','public.onboarding_tasks','UPDATE')and not has_table_privilege('authenticated','public.onboarding_task_decisions','SELECT')and not has_function_privilege('anon','public.create_default_onboarding_tasks(uuid)','EXECUTE')and not has_function_privilege('authenticated','public.get_onboarding_progress(uuid)','EXECUTE'),'raw tables and unscoped helpers closed');
create function pg_temp.fail_action()returns trigger language plpgsql as $$begin if new.action='checklist.created'then raise exception 'Synthetic checklist event failure';end if;return new;end$$;
create trigger fixture_checklist_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_action();
do $$begin begin perform pg_temp.decide('ee580000-0000-4000-8000-000000000040',(select v from st where k='create'));raise exception 'expected failure'using errcode='P0002';exception when sqlstate'P0001'then if sqlerrm<>'Synthetic checklist event failure'then raise;end if;perform pg_temp.check_it(true,'history failure reaches atomic boundary');end;end$$;
drop trigger fixture_checklist_failure on public.shared_action_events;
select pg_temp.check_it(not exists(select 1 from public.onboarding_tasks where id='ee580000-0000-4000-8000-000000000040')and not exists(select 1 from public.onboarding_task_decisions where id='ee580000-0000-4000-8000-000000000040'),'event failure leaves no partial task');
-- Setup completion is attributed and does not override archived/blocked/skipped operator work.
select pg_temp.decide(gen_random_uuid(),pg_temp.edit(md5('property-checklist:ee580000-0000-4000-8000-000000000001:contacts')::uuid,'archive'));
select set_config('p11.property_setup_scope','ee580000-0000-4000-8000-000000000001',true);
select public.complete_property_setup_tasks('ee580000-0000-4000-8000-000000000050','ee580000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111');
select pg_temp.check_it((select count(*)from public.onboarding_task_decisions where property_id='ee580000-0000-4000-8000-000000000001'and origin='property_setup'and actor_id='11111111-1111-1111-1111-111111111111'and input->>'setupDecisionId'='ee580000-0000-4000-8000-000000000050')=1,'setup helper attributes actual person and parent decision');
select pg_temp.check_it((select status='pending'from public.onboarding_tasks where id=md5('property-checklist:ee580000-0000-4000-8000-000000000001:contacts')::uuid),'setup leaves archived operator tasks unchanged');
select public.create_default_onboarding_tasks('ee580000-0000-4000-8000-000000000001');
select pg_temp.check_it((select status='completed'from public.onboarding_tasks where id=md5('property-checklist:ee580000-0000-4000-8000-000000000001:details')::uuid),'repeat initialization never resets reviewed progress');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where property_id='ee580000-0000-4000-8000-000000000001'and(training_eligible or(request::text||result::text)like'%Private task notes%')),'shared events carry safe evidence and no training permission');
insert into st values('page',pg_temp.read_tasks());
insert into public.onboarding_tasks(property_id,task_type,task_name,status)select'ee580000-0000-4000-8000-000000000001','legacy','Paged legacy task '||n,'pending'from generate_series(1,1001)n;
select pg_temp.check_it(pg_temp.read_tasks()->>'total'='1012'and pg_temp.read_tasks()->'stats'->>'total'='1011','full native counts exceed REST limit');
select pg_temp.check_it(jsonb_array_length(pg_temp.read_tasks('{"offset":1000}')->'items')=12,'last inventory page complete');
select pg_temp.check_it(pg_temp.read_tasks(jsonb_build_object('expectedHash',(select v->>'pageHash'from st where k='page')))->>'state'='history_changed','inventory pagination held after change');
insert into public.onboarding_task_decisions(id,task_id,property_id,org_id,actor_id,origin,kind,input,input_hash,after_state,result)select gen_random_uuid(),'ee580000-0000-4000-8000-000000000010','ee580000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111','operator','saved','{"reason":"Synthetic retained history"}','fixture','{}','{}'from generate_series(1,1001);
select pg_temp.check_it((pg_temp.read_tasks('{"kind":"history","taskId":"ee580000-0000-4000-8000-000000000010"}')->>'total')::int>1000,'complete history exceeds REST cap');
select pg_temp.check_it(jsonb_array_length(pg_temp.read_tasks('{"kind":"history","taskId":"ee580000-0000-4000-8000-000000000010","offset":1000}')->'items')>0,'later history page available');
-- Parent deletion is the only cleanup cascade.
delete from public.properties where id='ee580000-0000-4000-8000-000000000001';
select pg_temp.check_it(not exists(select 1 from public.onboarding_task_decisions where property_id='ee580000-0000-4000-8000-000000000001')and not exists(select 1 from public.onboarding_task_workspaces where property_id='ee580000-0000-4000-8000-000000000001'),'parent cleanup removes exact synthetic evidence');
select n as passed_assertions from assertion_count;
ROLLBACK;
